import {currentTimeZone,dateInZone} from './time.mjs';
import {escapeHtml as esc} from './core.mjs';
import {monthCells,monthLabel,localToday} from './organizer.mjs';
export function calendarMarkup(state,selectedDate){const active=state.events.filter(e=>!e.cancelled),events=active.filter(e=>e.date===selectedDate).sort((a,b)=>a.time.localeCompare(b.time)),today=dateInZone(),zone=currentTimeZone();return `<div class="two-columns"><section class="card"><div class="section-head"><h2>${esc(monthLabel(selectedDate))}</h2><button class="primary small-button" data-action="add-event">+ Compromisso</button></div><p class="card-intro">Horários locais · ${esc(zone)}. Nenhum convite é enviado automaticamente.</p><div class="calendar-controls"><button class="outline" data-action="calendar-month" data-offset="-1" aria-label="Mês anterior">←</button><button class="outline" data-action="calendar-today">Hoje</button><button class="outline" data-action="calendar-month" data-offset="1" aria-label="Próximo mês">→</button><label>Ir para a data<input type="date" id="calendar-date" min="1900-01-01" max="2200-12-31" value="${selectedDate}"></label></div><div class="calendar-grid" role="group" aria-label="Dias do mês">${['SEG','TER','QUA','QUI','SEX','SÁB','DOM'].map(d=>`<span class="calendar-weekday">${d}</span>`).join('')}${monthCells(selectedDate).map(d=>{const count=active.filter(e=>e.date===d.date).length;return `<button class="calendar-day ${d.currentMonth?'':'other-month'} ${d.date===today?'is-today':''} ${d.date===selectedDate?'selected':''}" data-action="select-date" data-date="${d.date}" aria-pressed="${d.date===selectedDate}" aria-label="${d.date.split('-').reverse().join('/')} · ${count} ${count===1?'compromisso':'compromissos'}">${d.day}${count?`<small>${count}</small>`:''}</button>`;}).join('')}</div><h3>${selectedDate.split('-').reverse().join('/')}</h3><div class="agenda-list">${events.map(e=>`<article class="event"><time>${esc(e.time)}</time><div><h3>${esc(e.title)}</h3><p>${e.duration} minutos · ${esc(e.timeZone||zone)}${e.seriesId?' · recorrente':''}</p></div><div class="calendar-event-actions"><button class="text-link" data-action="edit-event" data-id="${esc(e.id)}">Editar</button><button class="text-link" data-action="remove-event" data-id="${esc(e.id)}">Cancelar compromisso</button>${e.seriesId?`<button class="text-link" data-action="edit-event-series" data-id="${esc(e.id)}">Editar série</button><button class="text-link" data-action="cancel-event-series" data-id="${esc(e.seriesId)}">Cancelar série</button>`:''}</div></article>`).join('')||'<p class="muted">Há espaço no seu dia. Adicione um compromisso ou reserve uma pausa.</p>'}</div></section><aside class="stack"><section class="card"><h2>Seu Google Agenda</h2><p>Consulte sua agenda principal e revise os compromissos antes de guardar aqui.</p><button class="outline" data-action="gcal-open">Conectar ou consultar calendário</button></section><section class="card tinted"><h2>Seu tempo também precisa de espaço.</h2><p>Escolha o dia, informe o horário e organize o que merece sua atenção.</p><button class="outline" data-action="add-pause">Reservar uma pausa</button></section><section class="card"><h2>Seus próximos compromissos</h2>${active.filter(e=>e.date>=today).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)).slice(0,5).map(e=>`<button class="calendar-next" data-action="select-date" data-date="${e.date}"><b>${esc(e.title)}</b><span>${e.date.split('-').reverse().join('/')} · ${esc(e.time)}</span></button>`).join('')||'<p class="muted">Nenhum compromisso futuro.</p>'}</section><section class="card"><h2>Compromissos cancelados</h2>${state.events.filter(e=>e.cancelled).map(e=>`<p>${esc(e.title)} · ${esc(e.date)} <button class="text-link" data-action="restore-event" data-id="${esc(e.id)}">Restaurar ocorrência</button></p>`).join('')||'<p>Nenhum compromisso cancelado.</p>'}</section></aside></div>`;}
